A = [i*i - i + 1 for i in range(1,n+1)]
ans = []
for i in range(n):
    for j in range(i+1,n):
        for k in range(j+1,n):
            if (A[i]+A[j]+A[k])%3 == 0:
                ans += [(A[i],A[j],A[k])]
return len(ans)

